static const uint32_t ui_dashboard_q565_size = (uint32_t)sizeof(ui_dashboard_q565);

static inline uint32_t q565_hash_u16(uint16_t px)
{
    return (uint32_t)(((uint32_t)px * 2654435761u) >> 26) & 63u;
}

/*
 * Decode Q565 compressed image to RGB565 framebuffer.
 *
 * Parameters:
 *   src         Q565 compressed byte stream
 *   src_size    byte length of src
 *   dst         output buffer, uint16_t RGB565
 *   dst_pixels  capacity of dst in pixels
 *
 * Return:
 *    0  success
 *   -1  invalid argument
 *   -2  source ended early
 *   -3  output buffer too small or pixel count mismatch
 *   -4  invalid/reserved opcode
 *   -5  invalid DIFF data
 */
static inline int q565_decode_to_rgb565(
    const uint8_t *src,
    uint32_t src_size,
    uint16_t *dst,
    uint32_t dst_pixels
)
{
    if (src == 0 || dst == 0) {
        return -1;
    }

    uint16_t cache[64] = {0};
    uint16_t prev = 0;
    uint32_t si = 0;
    uint32_t di = 0;

    while (di < dst_pixels) {
        if (si >= src_size) {
            return -2;
        }

        uint8_t op = src[si++];

        if (op < 0x40u) {
            /* INDEX */
            uint16_t px = cache[op & 0x3Fu];
            prev = px;
            dst[di++] = px;
        }
        else if (op < 0x80u) {
            /* RUN */
            uint32_t run = (uint32_t)(op & 0x3Fu) + 1u;
            if (di + run > dst_pixels) {
                return -3;
            }

            while (run--) {
                dst[di++] = prev;
            }
        }
        else if (op < 0xC0u) {
            /* DIFF */
            int r = (int)((prev >> 11) & 0x1Fu);
            int g = (int)((prev >> 5)  & 0x3Fu);
            int b = (int)( prev        & 0x1Fu);

            r += (int)((op >> 4) & 0x03u) - 2;
            g += (int)((op >> 2) & 0x03u) - 2;
            b += (int)( op       & 0x03u) - 2;

            if (r < 0 || r > 31 || g < 0 || g > 63 || b < 0 || b > 31) {
                return -5;
            }

            uint16_t px = (uint16_t)(((uint16_t)r << 11) |
                                     ((uint16_t)g << 5)  |
                                     ((uint16_t)b));

            cache[q565_hash_u16(px)] = px;
            prev = px;
            dst[di++] = px;
        }
        else if (op == 0xFEu) {
            /* RAW16, little-endian RGB565 */
            if (si + 1u >= src_size) {
                return -2;
            }

            uint16_t px = (uint16_t)((uint16_t)src[si] |
                                     ((uint16_t)src[si + 1u] << 8));
            si += 2u;

            cache[q565_hash_u16(px)] = px;
            prev = px;
            dst[di++] = px;
        }
        else {
            /* 0xFF is reserved */
            return -4;
        }
    }

    return 0;
}

